// Check 1: Validate successful response
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Check 2: Validate data type
pm.test("RPM falloff is calculated as a number", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.rpmFalloff[0]).to.be.a("number");
});

// Check 3: Validate API contract response time (Increased to 500ms for GitHub Actions)
pm.test("Response time is less than 500ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(500);
});

// Check 4: Validate Content-Type
pm.test("Content-Type is application/json", function () {
    pm.response.to.have.header("Content-Type", "application/json; charset=utf-8");
});
